# Analyze 4-connected objects for encoded test grid already held in grid
from collections import deque, Counter
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  col=grid[r][c]
  if col==4 or (r,c) in seen: continue
  q=[(r,c)]; seen.add((r,c)); cells=[]
  while q:
   a,b=q.pop(); cells.append((a,b))
   for x,y in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
    if 0<=x<R and 0<=y<C and (x,y) not in seen and grid[x][y]==col:
     seen.add((x,y));q.append((x,y))
  comps.append((col,cells))
for col,cells in sorted(comps,key=lambda x:(min(r for r,c in x[1]),min(c for r,c in x[1]))):
 rs=[r for r,c in cells];cs=[c for r,c in cells]
 print(col,len(cells),(min(rs),max(rs),min(cs),max(cs)),(sum(rs)/len(rs),sum(cs)/len(cs)))
